contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking description; no precondition so it is always callable by the checker
    function run(string calldata description) public payable {
        // Try calling newEmergencyOracle and record whether it reverted
        bool reverted;
        c.newEmergencyOracle(description); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // The general invariant: the call reverts iff this contract is not an admin according to the public getter
        assert(reverted == (!c.isAdmin(address(this))));
    }

    receive() external payable { }
}

